import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.CHi0mXvr.js";var i=JSON.parse(`{"title":"ミーティングチェックリストおよび進行手順","description":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。","frontmatter":{"title":"ミーティングチェックリストおよび進行手順","description":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。","head":[["meta",{"name":"keywords","content":"スクラムバン, Scrumban, スクラムバン紹介, スクラムバンの概念, スクラムバンとは, Scrumban紹介, Scrumban概念, スクラムとカンバンの違い, スクラム vs カンバン, アジャイル方法論, アジャイルフレームワーク, カンバン方法論, スクラム方法論, スクラムバンプロセス, スクラムバン運用ガイド, スクラムバンボード, WIP制限, ワークフロー管理, カンバンボードの使い方, スクラムバンのメリット, スクラムバンの特徴, スクラムバンの効果, スクラムバン活用事例, スクラムバン導入効果, スクラムバン Jira設定, スクラムバンボードテンプレート, Scrumbanツール, スクラムバンコラボレーションツール, スクラムバンワークフロー, アジャイルプロジェクト管理, 業務効率化方法論, 反復的作業管理, ボトルネック解消"}],["meta",{"property":"og:title","content":"スクラムバン"}],["meta",{"property":"og:description","content":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。"}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/agile/activity.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/agile/checklistAndProcedure.html"}]],"sort":450},"headers":[],"relativePath":"ja/agile/checklistAndProcedure.md","filePath":"ja/agile/checklistAndProcedure.md","lastUpdated":1786532854000}`),a={name:`ja/agile/checklistAndProcedure.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="scrumban-ミーティングおよびイベントリストと進行方法の詳細説明" tabindex="-1">Scrumban ミーティングおよびイベントリストと進行方法の詳細説明 <a class="header-anchor" href="#scrumban-ミーティングおよびイベントリストと進行方法の詳細説明" aria-label="Permalink to “Scrumban ミーティングおよびイベントリストと進行方法の詳細説明”">​</a></h1><h2 id="_1-デイリースタンドアップ-daily-stand-up" tabindex="-1">1. <strong>デイリースタンドアップ (Daily Stand-up)</strong> <a class="header-anchor" href="#_1-デイリースタンドアップ-daily-stand-up" aria-label="Permalink to “1. デイリースタンドアップ (Daily Stand-up)”">​</a></h2><ul><li><strong>目的</strong>: チームメンバーが現在の作業状況を共有し、障害要因を把握して、当日の目標を明確にするため。</li><li><strong>進行方法</strong>: <ul><li>毎日決まった時間(通常は午前)に15分以内で進行。</li><li>会議時間を短く保つため、すべてのチームメンバーが立った状態で進行。</li><li>各チームメンバーが以下の3つの質問について簡潔に共有： <ul><li>昨日何をしたか？</li><li>今日何をする予定か？</li><li>現在の作業に障害要因はあるか？</li></ul></li><li>カンバンボードの前で進行し、作業の進捗状況を視覚的に確認。</li></ul></li></ul><h2 id="_2-バックログリファインメント-backlog-refinement" tabindex="-1">2. <strong>バックログリファインメント (Backlog Refinement)</strong> <a class="header-anchor" href="#_2-バックログリファインメント-backlog-refinement" aria-label="Permalink to “2. バックログリファインメント (Backlog Refinement)”">​</a></h2><ul><li><strong>目的</strong>: バックログアイテムを継続的にレビューおよび優先順位の調整を行い、作業単位に分割するプロセス。</li><li><strong>進行方法</strong>: <ul><li>定期的に (例：週に1〜2回) 進行。</li><li>PO (プロダクトオーナー) または関連する担当者が参加し、ストーリーの優先順位を調整。</li><li>チームと一緒にアイテムを分析し、必要な場合は業務をより小さな単位に分割。</li><li>作業に対する理解度と準備状態を高め、今後の作業に支障が出ないように準備。</li></ul></li></ul><h2 id="_3-リリースプランニング-release-planning" tabindex="-1">3. <strong>リリースプランニング (Release Planning)</strong> <a class="header-anchor" href="#_3-リリースプランニング-release-planning" aria-label="Permalink to “3. リリースプランニング (Release Planning)”">​</a></h2><ul><li><strong>目的</strong>: 中長期目標の設定と機能リリース計画の策定。</li><li><strong>進行方法</strong>: <ul><li>必要な時、または定期的に(例：毎月、四半期ごとに)進行。</li><li>チーム全体が参加し、目標とする機能とリリーススケジュールを協議。</li><li>カンバンボードとスクラムのスプリントの概念を適切に組み合わせて計画を立てる。</li><li>作業量(仕掛品、WIP)の制限を考慮して現実的なスケジュールを策定。</li></ul></li></ul><h2 id="_4-レビューミーティング-review-meeting" tabindex="-1">4. <strong>レビューミーティング (Review Meeting)</strong> <a class="header-anchor" href="#_4-レビューミーティング-review-meeting" aria-label="Permalink to “4. レビューミーティング (Review Meeting)”">​</a></h2><ul><li><strong>目的</strong>: 完了した作業の成果物を共有し、フィードバックを受ける場。</li><li><strong>進行方法</strong>: <ul><li>定期的、または必要に応じて進行。</li><li>チームメンバーが完了した作業のデモを行ったり、結果を共有する。</li><li>ステークホルダーおよびPOが参加してフィードバックを提供。</li><li>改善点と成功事例を一緒に議論する。</li></ul></li></ul><h2 id="_5-振り返りミーティング-retrospective" tabindex="-1">5. <strong>振り返りミーティング (Retrospective)</strong> <a class="header-anchor" href="#_5-振り返りミーティング-retrospective" aria-label="Permalink to “5. 振り返りミーティング (Retrospective)”">​</a></h2><ul><li><strong>目的</strong>: チームの作業プロセスとコラボレーション方法について振り返り、改善点を導き出す。</li><li><strong>進行方法</strong>: <ul><li>定期的に進行 (例：2週間に1回、または月1回)。</li><li>チームメンバー全員が参加。</li><li>一般的な進行手順： <ul><li>良かった点を共有</li><li>問題点と障害要因の導出</li><li>改善アイデアの議論</li><li>実行可能なアクションアイテムの選定</li></ul></li><li>アクションアイテムは次の期間に反映され、実行される。</li></ul></li></ul><h2 id="_6-優先順位の調整およびwip制限管理ミーティング" tabindex="-1">6. <strong>優先順位の調整およびWIP制限管理ミーティング</strong> <a class="header-anchor" href="#_6-優先順位の調整およびwip制限管理ミーティング" aria-label="Permalink to “6. 優先順位の調整およびWIP制限管理ミーティング”">​</a></h2><ul><li><strong>目的</strong>: カンバンの核心であるWIP制限を点検し、優先順位を調整してワークフローを最適化する。</li><li><strong>進行方法</strong>: <ul><li>必要に応じて随時進行可能。</li><li>チームが現在のWIP制限を超過していないか確認。</li><li>ボトルネック現象や遅延状況を把握し、解決策を議論。</li><li>作業追加時の優先順位の再調整。</li></ul></li></ul><hr><h1 id="追加の参考事項" tabindex="-1">追加の参考事項 <a class="header-anchor" href="#追加の参考事項" aria-label="Permalink to “追加の参考事項”">​</a></h1><ul><li><strong>カンバンボードの活用</strong>: すべてのミーティングはカンバンボード(実際のボードまたはデジタルボード)を中心に進行し、作業の視覚化が核心である。</li><li><strong>柔軟な進行</strong>: Scrumbanには厳格なスプリントがなく、必要に応じてミーティングの頻度と内容を調整できる。</li><li><strong>WIP制限の重要性</strong>: WIP制限をしっかり守ることが、作業効率の向上とボトルネックの最小化にとって重要である。</li></ul><hr>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};